import { makeArticle as a, section as s, type Article } from "@/lib/article-model";

const nztaVisitors = {label:"NZTA driving on New Zealand roads",url:"https://nzta.govt.nz/travelling-on-our-roads/visitors-and-new-residents/driving-on-nz-roads"};

export const rulesArticles: Article[] = [
  a({slug:"doc-campsite-rules",title:"DOC campsite rules every camper should know",description:"Bookings, quiet hours, rubbish, pets and local site conditions shape a stay on conservation land.",category:"Rules & safety",region:"DOC campsites",places:["Booked campsites","Non-bookable campsites","Conservation land","Great Walk camps"],imageAlt:"Department of Conservation campsite information board",intro:"A DOC booking accepts national terms and the local rules for that place. The individual campsite page remains essential because access, fire, water, dogs and vehicle conditions vary widely.",sections:[s("Use the booking honestly","Book the correct date, party and product, then keep confirmation available offline. Where pitches are not individually assigned, choose only from the area available on arrival.","Unused multi-day bookings can be cancelled after the first missed night under DOC terms. Do not hold a space with an empty tent when nobody intends to stay."),s("Respect shared hours","Standard DOC terms set quiet hours from 10 pm to 7 am unless local rules differ, with checkout generally by 10 am. Keep generators, music and vehicle movement within the site's limits.","A campsite booking does not grant use of nearby hut facilities. Use only the toilets, shelters and water points included with the booked product."),s("Leave the site ready","Take all rubbish, keep food secure and never dump grey water on the ground. Smoking and vaping are not permitted in huts or toilet blocks.","Pets and drones require explicit permission. Check the exact campsite page rather than treating a quiet location as implied approval." ),s("Booked, first come, or covered by a pass","Each campsite page states which system applies, and confusing them causes most arrival problems. A Campsite Pass is a way of paying rather than a reservation, so it does not hold a place at a site that requires booking, and it does nothing at a first-come ground that is already full.","Where booking is required, book for the party and vehicle you are actually bringing. Carry the confirmation offline, because reception at DOC campsites is frequently absent and a booking you cannot produce is hard to defend to a warden allocating a full ground.",["A pass is not a booking","Carry confirmations offline","Book the real vehicle and party size"]),s("Water is often untreated","Many DOC sites draw from streams or roof tanks and the supply is not treated. Giardia is present in New Zealand water and a clear stream tells you nothing about it. Boil for at least a minute, filter, or use chemical treatment, and do not assume a tap is safe because it exists.","Carry enough drinking water to stay independent for a day. Tanks run dry, boil-water notices appear, and a campsite listed as having water can turn out to have a broken supply with no warning."),s("Generators, drones and dogs","Generator use is restricted or prohibited at many sites, and where permitted it is usually limited to set hours. Drones require a concession on public conservation land in most circumstances, and flying one over a campground without permission is both unlawful and deeply unpopular.","Dogs are prohibited on most public conservation land because of the risk to ground-nesting birds and kiwi. A few campsites permit them; the majority do not, and a permit is required in some areas. Check the specific site rather than assuming.",["Drones need a concession on DOC land","Dogs banned at most DOC sites","Generators are restricted or banned"]),s("Maximum stay and site conduct","Most DOC campsites have a maximum stay, commonly a small number of consecutive nights, intended to stop long-term occupation. Wardens do enforce it at popular grounds during summer, and moving a vehicle a few metres does not reset it.","Keep to the marked pitch, do not extend beyond it with awnings or gear where space is tight, and observe quiet hours. These grounds are shared, frequently full, and the enjoyment of everyone depends on people staying within their own space."),{heading:"Arriving and settling in",body:["Turn up in daylight where you can. Choosing a pitch, judging drainage, spotting overhead branches and levelling a vehicle are all considerably harder in the dark, and a site that would obviously be wrong at 4pm is easy to accept at 9pm when you are tired.","Pay on arrival where an honesty box or self-registration applies rather than intending to sort it later. Wardens do check, the fee is small, and the system only works because most people pay without being asked.","Set up within the marked pitch and leave room for whoever arrives after you. At a busy ground in summer, spreading gear across two spaces is the difference between the site holding everyone and people being turned away."]},s("If the campsite is full","Popular DOC grounds fill by mid-afternoon over summer and there is no overflow. Creating an extra pitch on the grass, the access lane or beside the toilet block is not an option, and wardens will move you on.","Identify a legal fallback before you arrive rather than after. A holiday park half an hour away is a much better outcome than a late drive on an unfamiliar road looking for anywhere that will take you.",["Popular grounds fill by mid-afternoon","There is no overflow area","Know your fallback before arriving"])],sources:[{label:"DOC accommodation booking terms",url:"https://www.doc.govt.nz/parks-and-recreation/places-to-stay/bookings-terms-and-conditions/huts-campsites-cabins-and-lodges-terms-and-conditions/"}]}),
  a({slug:"doc-hut-rules-etiquette",title:"DOC hut rules and backcountry etiquette",description:"Bookings, bunks, cooking and emergency shelter work differently from ordinary accommodation.",category:"Rules & safety",region:"New Zealand backcountry huts",places:["Great Walk huts","Serviced huts","Standard huts","Basic huts"],imageAlt:"Interior of a shared DOC backcountry hut",intro:"A hut booking buys access to shared shelter, not a private room or a specific bunk unless the product says otherwise. Every person still needs the equipment and judgement to cope if the hut is full, damaged or unreachable.",sections:[s("Carry the right authority","Book named huts and dates where reservations apply, or carry the appropriate tickets or pass for non-bookable facilities. Proof should remain available without reception.","Do not rely on unbooked space at a popular hut. Emergency use remains possible in adverse conditions, which is another reason to keep gear compact and considerate."),s("Live in one room","Select an available bunk, keep sleeping gear together and observe quiet hours. Cook only in the designated area, supervise flames and never leave food that attracts rodents.","Use heating fuel conservatively and follow the hut's fire instructions. Wet clothing should not block exits, bunks or the cooking space."),s("Leave safely","Clean benches, sweep where requested, close doors and carry every piece of rubbish out. Treat or boil water according to current advice.","Record intentions with a trusted person and carry navigation and emergency equipment. The hut does not make the track safe or guarantee rescue communication." ),s("Nobody is turned away","Bunks in non-bookable huts are first come, and the long convention is that a full hut means floor space rather than a closed door. Do not walk on into the dark because the bunks are taken, and equally do not expect someone to give up a bunk they reached first.","Carry a mat so sleeping on the floor is genuinely viable, and where the site permits camping and the weather allows, a tent gives you a real alternative. On popular tracks in summer, plan on the assumption that the hut will be full.",["Full hut means floor space","Carry a mat regardless","Assume full in summer"]),s("Fill in the hut book, every time","The intentions book is the first thing search and rescue reads when a party is overdue, and an accurate entry has shortened many searches. Record the date, your party, where you came from and where you are going next.","Sign out as well as in where the book allows it. A party recorded as arriving and never leaving generates a search that did not need to happen."),s("Fire, fuel and cooking","Where a hut has a stove, use the firewood sparingly and restock the kindling for whoever arrives next in worse weather than you had. Do not burn rubbish in the hut stove; it damages the flue and leaves the smell for everyone.","Cook on your own stove, in the designated area or outside, never in a tent or a confined porch. Carry enough fuel for the trip plus a margin, because there is nothing available at a hut and a borrowed stove is an imposition.",["Restock kindling before leaving","Never burn rubbish in the stove","Carry your own stove and fuel"]),s("Leaving it better than you found it","Sweep, close the shutters and door catches properly against wind and rodents, and carry out everything you carried in including food scraps. There is no rubbish collection at a backcountry hut, so whatever you leave stays until another walker removes it.","Report damage, a failed water supply or a hazard to DOC after the trip. Maintenance is prioritised on what gets reported, and a short message can stop the next party arriving to a building that does not work."),{heading:"Sharing a hut with strangers",body:["A backcountry hut puts a dozen people who have never met into one room after a hard day. Almost all of the etiquette follows from that: keep your gear in your own space, do not run a stove or a bright light in someone's face, and accept that somebody will snore.","Offer space on the bench and the bunks rather than waiting to be asked. Parties arriving late are usually wet and cold, and the difference between a welcoming hut and a miserable one is entirely down to whoever got there first.","Head torches on red mode after dark, and pack your bag in the porch if you are leaving before the others. Rustling a dry bag at 5am is the single most complained-about behaviour in New Zealand huts."]},s("Booking seasons and what changes","Great Walk huts run a booked season with higher fees, wardens and full facilities, then revert to a lower standard and price outside it. Gas, heating and sometimes the water supply are removed in the off season.","Check what the hut actually offers for your dates rather than the summer description. An off-season Great Walk hut can be considerably colder and barer than the photographs suggest.",["Facilities drop outside the season","Gas and heating may be removed","Check the hut for your actual dates"])],sources:[{label:"DOC hut categories",url:"https://www.doc.govt.nz/parks-and-recreation/places-to-stay/stay-in-a-hut/hut-categories/"}]}),
  a({slug:"dogs-camping-new-zealand",title:"Camping with a dog in New Zealand",description:"Conservation land, council reserves and holiday parks have different permissions even when the dog stays in a vehicle.",category:"Rules & safety",region:"New Zealand",places:["DOC campsites","National parks","Council campgrounds","Holiday parks"],imageAlt:"Dog on lead beside a legal New Zealand campsite",intro:"Dog access must be checked for the exact land. Native wildlife protection means many conservation areas prohibit pets completely, including animals left inside a vehicle.",sections:[s("DOC rules are strict","Pets are generally not allowed at DOC camps, huts, lodges or cottages without written approval. Some campsites expressly allow dogs under listed conditions, but national parks remain no-dog environments.","A dog may travel to a hut only where dog access is allowed and must remain outside the hut. Search the exact place page before departure."),s("Councils and private parks","Council camping areas can combine freedom-camping bylaws with separate dog-control rules. A site may allow a vehicle overnight but prohibit dogs in the reserve.","Holiday parks set their own conditions, often by season, size or site type. Confirm in writing and disclose every animal when booking."),s("Protect wildlife and neighbours","Use a lead where required, prevent barking and collect all waste. Keep dogs away from nesting birds, seals, livestock and pest-control poison zones.","Carry vaccination information and a secure restraint for travel. If access is unclear, choose a dog-friendly commercial site rather than testing the rule on arrival." ),s("Most conservation land is closed to dogs","Dogs are prohibited on the large majority of public conservation land, including most national parks, because kiwi and other ground-nesting birds have no defence against them. A single dog off a lead has killed multiple kiwi in a night, and this is why the restriction is absolute rather than discretionary.","A limited number of DOC areas permit dogs, and some require a permit obtained in advance. Check the specific place before you travel rather than assuming, because the penalties are significant and the risk to wildlife is real.",["Most national parks ban dogs entirely","Some areas need a permit in advance","Check the specific site, never assume"]),s("1080 and pest control operations","Aerial 1080 is used widely for possum and rat control and is lethal to dogs, both directly and through eating poisoned carcasses, with the risk persisting for months after an operation. Warning signs are posted at access points and operations are published in advance.","Check for current and recent operations along your route before travelling with a dog, and keep it leashed and muzzled where advised. This is the single largest avoidable risk to a dog on a New Zealand trip."),s("Holiday parks and council reserves","Many holiday parks accept dogs but a substantial number do not, and those that do frequently exclude them during peak season or require them to be crated or leashed at all times. Booking without confirming the policy is a common way to arrive with nowhere to stay.","Council reserves and beaches often have seasonal dog restrictions protecting nesting shorebirds, typically over spring and summer. These are signed locally and enforced, and they change between neighbouring councils.",["Confirm the dog policy when booking","Peak season exclusions are common","Beach restrictions protect nesting birds"]),s("Practical travel with a dog","A dog must be restrained in a vehicle, and travelling on the back of a ute requires proper securing. Heat in a parked vehicle kills quickly here, and shade moves, so a dog cannot be left while you do a walk that excludes them.","Plan the trip around the places that accept dogs rather than hoping to improvise. In practice that usually means coastal walkways, forestry tracks, regional parks and holiday parks rather than national parks and Great Walks."),{heading:"Where a dog can actually go",body:["In practice the workable options are holiday parks that accept dogs, council reserves outside restricted seasons, forestry and regional park tracks, and most beaches outside nesting periods. That is a real trip, but it is a different trip from one built around national parks.","Several regional parks around Auckland and Wellington allow dogs on lead, and many coastal walkways permit them year-round. These tend to be places where kiwi and ground-nesting birds are absent or already fenced out.","Plan the route around the dog-friendly places first and fill in around them. Attempting a standard South Island itinerary with a dog produces a trip where somebody waits in the vehicle for most of the good walks."]},s("Kiwi aversion training","Some regions offer kiwi aversion training for dogs, and in a few areas it is a condition of access. It is worth doing for any dog spending time in Northland, Coromandel or the West Coast even where it is not required.","Even a trained dog must be under control. Most kiwi killed by dogs are killed by pets whose owners were certain their animal would not chase anything.",["Aversion training is required in some areas","Trained dogs still need control","Most incidents involve pets, not strays"])],sources:[{label:"DOC pets on conservation land",url:"https://www.doc.govt.nz/parks-and-recreation/know-before-you-go/pets-on-conservation-land/"}]}),
  a({slug:"kauri-dieback-camping-travel",title:"Kauri dieback: clean gear before northern camps and walks",description:"Soil on boots, tent pegs and tyres can carry a pathogen that kills kauri trees.",category:"Rules & safety",region:"Northland and Auckland forests",places:["Waipoua Forest","Waitākere Ranges","Coromandel","Kauri hygiene stations"],imageAlt:"Kauri forest track hygiene station",intro:"Kauri dieback moves in contaminated soil and has no cure. Camping gear creates many contact points, so cleaning only hiking boots is not enough.",sections:[s("Arrive clean","Scrub every visible clump of soil from footwear, poles, tent pegs, mats, bike tyres and tools before entering kauri country. Clean at home or another suitable hard surface where wash water cannot reach the forest.","Use every hygiene station in the direction shown, even when equipment looks clean. Disinfectant works only after soil has been removed."),s("Stay on open tracks","Obey closures, barriers and boardwalk instructions. Stepping around mud widens the contaminated area and can move soil toward kauri roots.","Choose another walk when a track is closed. An old guide or GPS line does not authorise access through a protection zone."),s("Clean between regions","Repeat cleaning before leaving a forest area and before the next kauri catchment. Store dirty equipment separately until it can be treated properly.","Dogs can also move contaminated soil and may be prohibited for additional conservation reasons. Check both kauri and pet rules." ),s("How the disease actually spreads","Kauri dieback is caused by a soil-borne pathogen that moves in a single gram of soil on a boot, a tent peg, a bike tyre or a dog's paws. There is no cure and infected trees die. The spread is almost entirely human-assisted, which is why the hygiene stations exist.","The critical part is mechanical: you must physically scrub the soil off before the disinfectant does anything. Spraying over caked mud achieves nothing at all, and this is the step most visitors skip.",["Scrub the soil off first, then spray","One gram of soil can carry it","Spraying over mud does nothing"]),s("Stay on the structures","In kauri forest the boardwalks and matting are not a convenience, they are the containment. Stepping off to pass someone, to take a photograph or to reach a better angle puts soil onto your boots from within the root zone, which extends well beyond the visible canopy.","Kauri roots are shallow and wide, and compaction damages them directly as well as spreading the pathogen. The structures exist because walking on the ground near a kauri harms it twice."),s("Some tracks are closed permanently","Large parts of the Waitākere Ranges and other northern forests have been closed under rāhui and formal closures, and some will not reopen. Old blog posts and guidebooks describing these walks circulate widely and are no longer accurate.","Check the current DOC and Auckland Council status before planning a walk to a specific tree or track. Entering a closed area is both an offence and a direct threat to the stand it is protecting.",["Old guides list closed tracks","Check DOC and council status first","Rāhui closures are not advisory"]),s("Clean gear before you arrive, not just between tracks","Arriving in Northland or the Coromandel with soil from another region on your boots is how the pathogen moves between forests. Clean and dry footwear, tent pegs, poles and groundsheets before you travel north, not only at the track entrance.","The same applies to vehicles on unsealed forestry roads and to dogs, which are prohibited in most kauri areas partly for this reason. Treat soil as the thing you are managing rather than mud as an inconvenience."),{heading:"Why it matters beyond the trees",body:["Kauri are foundation species: entire communities of plants, fungi and invertebrates depend on them and some exist nowhere else. Losing a stand is not losing trees, it is losing the system built around them over centuries.","They are also taonga, with individual trees named and carrying whakapapa and history. Tane Mahuta and Te Matua Ngahere are not tourist attractions in the ordinary sense, and the rahui placed over affected forests reflect that standing.","The hygiene measures ask very little of any individual visitor. Thirty seconds at a cleaning station and staying on a boardwalk is the entire contribution required, and it is currently the only thing slowing the spread."]},s("What to do if you find a sick tree","Symptoms include yellowing foliage, canopy thinning, dead branches and a gum bleed at the base of the trunk. If you see them, note the location and report it rather than approaching for a closer look.","Do not take samples, touch the bleeding gum or move soil away from the tree. Reporting through DOC or the regional council is genuinely useful, because surveillance depends heavily on public reports.",["Gum bleed at the trunk base is the sign","Report it, do not investigate","Never move soil near a sick tree"])],sources:[{label:"DOC kauri dieback guidance",url:"https://www.doc.govt.nz/nature/pests-and-threats/diseases/kauri-dieback/"}]}),
  a({slug:"new-zealand-biosecurity-camping-gear",title:"New Zealand biosecurity for camping and hiking gear",description:"Declare risk items at the border and clean equipment before it moves between waterways and forests.",category:"Rules & safety",region:"New Zealand border and outdoors",places:["Airport arrivals","Hiking boots","Tents","Fishing gear","Freshwater equipment"],imageAlt:"Clean hiking boots prepared for New Zealand biosecurity",intro:"Used outdoor equipment can carry seeds, soil, insects and aquatic pests. Biosecurity starts at the border and continues when gear moves between New Zealand ecosystems.",sections:[s("Declare on arrival","Declare used boots, tents, fishing equipment, food, plant material and animal products when required by the New Zealand Traveller Declaration. A declaration lets officers assess and clean items; concealment creates the risk and penalty.","Pack gear where it can be inspected easily. Scrub soil and plant material before flying, but still declare the item when the question applies."),s("Clean between places","Check, clean and dry boats, waders, paddles and fishing gear before another waterway. Microscopic pests survive in moisture that appears harmless.","Brush seeds and mud from tyres, pegs and walking gear before changing catchments. Use local wash stations where supplied."),s("Do not improvise disposal","Never release bait, aquarium water, food plants or untreated wash water into the environment. Use rubbish and wastewater systems designed for the material.","Follow regional pest-control notices and temporary rāhui. Local restrictions may protect a species or place beyond the national minimum." ),s("Declare everything at the border","New Zealand's biosecurity regime is among the strictest anywhere and instant fines apply for undeclared risk goods. Used hiking boots, tents, camping equipment, bicycles and anything that has been in soil or fresh water must be declared, and food of almost any kind must be declared.","Declaring costs nothing and takes a minute. The officer may inspect and clean the item and send you on your way. Failing to declare is what produces the fine, not the item itself, and the distinction catches out a lot of well-meaning visitors.",["Declaring is free, not declaring is fined","Used boots and tents must be declared","All food must be declared"]),s("Clean gear before you pack it","Arrive with boots scrubbed free of soil, tents dry and free of seeds and insects, and any water-contact equipment cleaned and dried. Gear that arrives visibly dirty is more likely to be held for treatment, which can mean collecting it later or losing it.","Check pockets and stuff sacks for seeds, leaf litter and dried mud. A tent packed damp in another country frequently arrives with a colony of something, and it is easier to deal with at home."),s("Check, Clean, Dry between waterways","Didymo and other freshwater pests move on damp gear between catchments. The requirement applies to boots, waders, tents, fishing equipment, paddleboards and anything else that has been in fresh water, and it applies within New Zealand as much as at the border.","Clean thoroughly, then dry completely and leave it dry for at least 48 hours before entering another waterway. Where drying is not practical, use the recommended treatment solutions instead.",["Applies within New Zealand, not just entry","Dry for 48 hours before the next waterway","Covers boots, tents and boards"]),s("Moving between islands and regions","There are internal controls too. Ulva Island, Rakiura and other predator-free sanctuaries require you to check bags for rodents and seeds before boarding, and the checking stations at the wharves are not a formality. A single rat reaching an island undoes decades of work.","Fruit fly and other regional controls occasionally restrict moving fresh produce within the country. Where a control area is in force it is signed and publicised, and the rules apply to a campervan fridge as much as to a truck."),{heading:"Why the rules are this strict",body:["New Zealand's native species evolved with no land mammals and almost no defences against them. Introduced predators, weeds and diseases have already caused extinctions, and the border controls exist because the country is still losing species to things that arrive in luggage.","Foot and mouth, fruit fly and myrtle rust are the incursions with the largest economic and ecological consequences, and each has been intercepted at the border more than once. The inspection you find inconvenient is the reason those interceptions happen.","The process is quick and officers are helpful when you declare. The penalty is for concealment rather than for owning muddy boots, and the difference is entirely in whether you tick the box."]},s("Leaving the country again","Some items you acquire here cannot leave, and others need paperwork. Anything made from protected species, greenstone taken from certain areas, and some plant material all carry restrictions worth checking before you pack.","Australia in particular has its own strict border rules, so gear that arrives here muddy will face the same scrutiny on the way out. Clean everything again before the return flight.",["Check restrictions before taking items out","Australia is equally strict inbound","Clean gear again before flying home"])],sources:[{label:"New Zealand biosecurity arrival guidance",url:"https://www.mpi.govt.nz/travel-and-recreation/arriving-in-new-zealand/"}]}),
  a({slug:"sandflies-new-zealand-camping",title:"Sandflies in New Zealand: how to camp with fewer bites",description:"West Coast, Fiordland and damp bush camps need screens, repellent and a deliberate arrival routine.",category:"Rules & safety",region:"West Coast and Fiordland",places:["Milford Sound","Haast","West Coast","Rakiura"],imageAlt:"Fiordland campsite near sandfly habitat",intro:"Sandflies are most intense around damp, sheltered water edges, especially on the West Coast and in Fiordland. They are irritating rather than a reason to avoid the region, but small camp habits make a large difference.",sections:[s("Choose the pitch carefully","Moving air and distance from still water can reduce activity. Keep doors and screens closed before unloading, because an open campervan becomes a trap for the rest of the night.","Wear long sleeves, socks and trousers at dawn and dusk. Apply an effective repellent according to its label and reapply after swimming or heavy rain."),s("Manage the interior","Repair screen holes before reaching remote camps and avoid bright interior lights with doors open. Cook outside only as conditions allow, then move inside quickly.","Do not spray insecticide around food, children or unventilated sleeping spaces. Use products only where their directions permit."),s("Treat bites and watch reactions","Wash bites, avoid scratching and use ordinary itch relief when suitable. Seek medical advice for signs of infection or a severe allergic reaction.","Sandfly pressure changes with wind, temperature and rainfall. A nearby exposed holiday park can be a sensible alternative to a beautiful but still riverside camp." ),s("Where and when they are worst","Sandflies concentrate on the West Coast, throughout Fiordland, around the Catlins and in damp bush near water anywhere in the country. They are worst at dawn and dusk, in still conditions and close to rivers and coast, and they largely disappear in wind, cold and full sun.","The transition can be abrupt. The eastern side of the Haast Pass is close to sandfly-free and the western descent is not, so have repellent accessible in the cab rather than packed away before you cross.",["West Coast, Fiordland, Catlins are worst","Dawn, dusk and still air","Wind and cold suppress them"]),s("What actually works","Repellents containing DEET or picaridin are the effective options, applied to skin before you leave the vehicle rather than after the first bites. Reapply after swimming or sweating, and cover ankles, wrists and the back of the neck, which is where most bites land.","Physical barriers work better than chemistry. Long sleeves, long trousers and socks in the evening remove most of the problem, and a head net is not an overreaction on the Milford road in summer."),s("Managing the tent and the vehicle","Check the insect mesh for holes before you travel, because a single tear makes the tent useless against them. Enter and exit quickly, and get in the habit of zipping fully rather than most of the way.","Sandflies follow you into a van and stay. Closing up before dusk rather than after it, and killing the few that got in before you settle, saves a long night. A small battery fan disrupts their flight and helps more than it sounds.",["Check the mesh before you leave home","Close up before dusk, not after","A small fan genuinely helps"]),s("Treating the bites","The reaction is delayed and the itch peaks a day or two later, often lasting a week. Antihistamine cream or tablets help, as does not scratching, which is easier said than done and is what turns a bite into an infected sore.","Some people react far more strongly than others, and reactions can build over a trip rather than settle. Carry treatment with you rather than planning to buy it, because the places where you need it are the places with no pharmacy."),{heading:"Planning a trip around them",body:["On the West Coast and in Fiordland, choose sites with some exposure to breeze rather than tucked into sheltered bush beside a river. The most beautiful sheltered spot is reliably the worst one, and a slightly windier pitch makes for a far better evening.","Time your outdoor tasks. Setting up camp, cooking and eating are all much easier in the middle of the day or in wind than at dusk, so arriving early is worth more here than almost anywhere else in the country.","Maori tradition holds that Hine-nui-te-po released the namu at Milford to stop people lingering and becoming too enchanted by the place. Having spent an evening there without repellent, the story is hard to argue with."]},s("What does not work","Citronella candles, ultrasonic devices and wristbands are all widely sold and none of them meaningfully reduce bites. Neither does eating garlic or taking vitamin B, despite how often both are recommended.","Spend the money on a proper repellent and long sleeves instead. The things that work are unglamorous and reliable, and the things that do not are the ones sold at the campground shop.",["Citronella and wristbands do not work","Ultrasonic devices are useless","DEET or picaridin plus clothing"])]}),
  a({slug:"new-zealand-severe-weather-camping",title:"Severe weather and camping in New Zealand",description:"Official warnings, river levels and shelter matter more than the icon in an ordinary forecast.",category:"Rules & safety",region:"New Zealand",places:["MetService warnings","Civil Defence alerts","Flood-prone camps","Exposed coasts"],imageAlt:"Dark storm clouds over a New Zealand campsite",intro:"New Zealand weather can shift from local inconvenience to road closure or evacuation. Campers need to connect the warning to the exact valley, coast, river and road rather than treating rain as a uniform national event.",sections:[s("Use official warnings","Check MetService severe weather information and local Civil Defence channels before departure and during any active system. Waka Kotahi and councils provide the road consequences.","Weather at a nearby town may not describe an alpine pass or coastal camp. Read the warning area and expected timing."),s("Move before conditions peak","Leave river flats, low coastal ground and exposed forest camps early when authorities advise it. Do not wait for visible flooding or falling branches to confirm the forecast.","Park facing a safe exit without blocking others. Keep keys, shoes, warm layers and essential medication ready."),s("After the storm","Assume fords, slips and unsealed roads may remain unsafe after rain ends. Never drive through floodwater or around a closure.","Recheck drinking-water notices and campground status. A calm morning does not prove damaged access has reopened." ),s("Weather here changes faster than the forecast","New Zealand sits in the path of systems crossing the Tasman with nothing to slow them, and conditions can shift completely within an hour. A forecast for a town tells you relatively little about a pass, an exposed coast or a valley twenty minutes away.","Check MetService for the specific location rather than the region, and check again in the morning before committing to an exposed site or an alpine road. Treat a forecast more than two days out as an indication rather than a plan.",["Check the location, not the region","Recheck each morning","Two-day forecasts are indications"]),s("Wind is the most common problem","More camping trips are damaged by wind than by rain. Awnings left out, tents pitched broadside and roof vents left open account for most of it, and wind commonly rises through the evening rather than dropping off at dusk.","Pitch with the smallest profile into the wind, use every guyline rather than the minimum, and bring awnings in before you go to bed rather than when they start moving. Choose shelter over the view when the forecast is strong."),s("Flooding and river flats","Braided riverbeds and low river flats look like ideal camping and are the most dangerous ground available in heavy rain. Rivers here rise extremely quickly, and rain falling in the headwaters hours away and out of sight is what catches people out.","Camp above the obvious flood level, never on a gravel bar or island, and leave if the water starts rising or discolouring. Do not attempt to drive through floodwater; the depth and whether the road is still under it are both unknowable from the vehicle.",["Never camp on a gravel bar","Rain upstream floods clear skies","Never drive through floodwater"]),s("Warnings and what to do with them","MetService issues watches and warnings, Civil Defence publishes emergency advice, NZTA covers road closures and DOC posts track and campsite alerts. Between them they cover everything that would change your plans, and they need checking while you still have signal.","When a severe weather warning covers your area, move to a serviced campground, a cabin or a town. That is not an overreaction: exposed camping in a genuine New Zealand storm is unpleasant at best and dangerous at worst."),{heading:"Making the call to move",body:["The decision people get wrong is staying put because moving feels like abandoning the plan. Relocating to a serviced campground, a cabin or a town before a front arrives costs a night's fee and a short drive, and it removes almost all of the risk.","Make the call while you still have daylight and reception rather than once conditions have started. Driving out of an exposed site in a rising storm after dark is considerably worse than either staying put or having left earlier.","Identify a specific fallback for each region instead of a vague intention to find something. Knowing the name of the holiday park and that it has space is what makes the decision easy at the moment you need to make it."]},s("After the weather passes","Slips, fallen trees and washed-out fords can persist for days after the rain stops, and road openings lag behind the forecast. Check conditions again before moving rather than assuming a clear morning means a clear route.","Rivers stay high and discoloured well after the rain, so crossings that looked fine on the way in may not be on the way out. Rebuild the day around what the road and river are doing, not the sky.",["Roads reopen after the weather clears","Rivers stay high for longer","Recheck before moving on"])],sources:[{label:"MetService severe weather",url:"https://www.metservice.com/warnings/home"},{label:"Get Ready New Zealand",url:"https://getready.govt.nz/"}]}),
  a({slug:"earthquake-tsunami-camping-new-zealand",title:"Earthquakes and tsunami safety for New Zealand campers",description:"Know the evacuation route before sleeping on the coast and act on natural warning signs immediately.",category:"Rules & safety",region:"New Zealand coasts",places:["East Coast","Kaikōura","Wellington","West Coast","Tsunami evacuation zones"],imageAlt:"Tsunami evacuation route sign on the New Zealand coast",intro:"Many memorable camps sit close to the sea. Before nightfall, identify whether the place lies in a tsunami evacuation zone and where higher ground can be reached without depending on a vehicle.",sections:[s("Before the shaking","Use local evacuation maps and signs to find the route and safe area. Keep shoes, torch, warm clothing and essential medication easy to grab.","Do not park across an evacuation path. In a crowded coast camp, walking can be faster and safer than joining a vehicle queue."),s("Stay away until cleared","Tsunami waves can continue for hours and the first may not be the largest. Remain outside the zone until officials give the all-clear.","Expect damaged roads and power loss. Use radio and official channels, conserve phone battery and help others without returning to collect equipment." ),s("Long or strong, get gone","This is the official rule and it is worth memorising exactly. If an earthquake at the coast lasts longer than a minute, or is strong enough that you cannot stand up, move immediately to high ground or as far inland as you can. Do not wait for an official warning, because for a local-source tsunami there will not be time for one.","Go on foot if the ground allows it, because roads jam and bridges may be damaged. Aim for at least 35 metres above sea level or a kilometre inland, and stay there until officials say it is safe rather than returning after the first wave.",["Long or strong, get gone","Do not wait for an official warning","35 m up or 1 km inland, on foot"]),s("Choosing a coastal campsite with this in mind","When you arrive at a coastal site, spend a minute identifying the way to high ground. Many New Zealand coastal areas have marked tsunami evacuation routes and blue lines showing the safe zone boundary, and knowing where yours is costs nothing.","This matters most on the East Coast, Kaikōura, Wellington's south coast and the Bay of Plenty, all of which face significant local-source risk. It applies to a beachfront holiday park as much as a remote DOC site."),s("During the shaking","Drop, cover and hold on. In a tent, stay put and protect your head; the tent itself is unlikely to hurt you. In a campervan, stay inside and hold on rather than trying to get out, and if you are driving, pull over clear of bridges, banks and power lines and stay in the vehicle.","Expect aftershocks, sometimes for weeks. After a significant shake, check for damage to your site, avoid slopes and cliff bases that may now be unstable, and be cautious around any structure that has moved.",["Drop, cover, hold on","Stay in the vehicle if driving","Aftershocks continue for weeks"]),s("Being prepared to be self-sufficient","A significant earthquake can close roads, cut power and disrupt fuel and water supply for days, and in a remote area you may be genuinely on your own for a while. Carrying water, food, warm clothing, a torch and a charged power bank covers most of it.","Keep the fuel tank above half in seismically active regions where practical, and know that mobile networks may be congested or down. A battery radio is a genuinely useful item, because emergency broadcasting continues when the network does not."),{heading:"Why this is worth thinking about here",body:["New Zealand straddles an active tectonic plate boundary, records thousands of earthquakes a year and has a documented history of large local-source tsunami. The 2016 Kaikoura earthquake generated waves within minutes of the shaking.","For a local-source event no warning system can help in time. The shaking itself is the warning, which is why the official advice is built entirely around what you do without being told anything by anyone.","None of this should stop anyone camping on the coast. It takes one minute on arrival to work out where high ground is, and that single habit covers the whole risk."]},s("Distant-source tsunami","A tsunami generated far away gives hours of warning, and official alerts will reach you through Civil Defence, radio and emergency mobile alerts. That is the situation where waiting for instruction is correct.","The distinction matters: local-source means move immediately without waiting, distant-source means follow the official advice. Knowing which one you are in comes down to whether you felt the earthquake yourself.",["Felt it? Move immediately","Did not feel it? Follow official advice","Emergency mobile alerts reach most phones"])],sources:[{label:"Get Ready earthquake advice",url:"https://getready.govt.nz/emergency/earthquakes"},{label:"Get Ready tsunami advice",url:"https://getready.govt.nz/emergency/tsunami"}]}),
  a({slug:"volcanic-safety-new-zealand-travel",title:"Volcanic safety around Tongariro, Ruapehu and Rotorua",description:"Alert levels, track closures and geothermal barriers exist because hazards can change without visible warning.",category:"Rules & safety",region:"Central North Island",places:["Tongariro National Park","Mount Ruapehu","Rotorua","GeoNet"],imageAlt:"Volcanic landscape in Tongariro National Park",intro:"Volcanic areas are active systems, not scenic sets. GeoNet alert levels, DOC closures and local operator instructions provide different parts of the safety picture and should all be checked.",sections:[s("Read current status","Review GeoNet volcanic alert information and DOC track notices before travelling. An alert level communicates activity, but it does not replace access restrictions for a specific walk.","Weather and volcanic hazards are separate. A low volcanic alert does not make an alpine crossing safe in high wind, snow or poor visibility."),s("Stay behind barriers","Geothermal crust can be thin and water can be near boiling. Remain on boardwalks and never step around a barrier for steam, colour or a photograph.","Keep children close and avoid touching pools, vents or runoff. Sulphur smell alone does not indicate the level of danger."),s("Have a changeable plan","Use shuttle and track operators that follow current access guidance. Carry layers, navigation and emergency supplies even on popular routes.","If activity closes a place, choose another region or lower walk. A holiday schedule never justifies crossing a closure." ),s("The alert level system","GeoNet publishes a Volcanic Alert Level from 0 to 5 for each active volcano, and access restrictions follow it. Level 1 means minor unrest and is common at Ruapehu and White Island; level 2 and above bring closures of tracks and, at Tongariro, sections of the Alpine Crossing.","Check the current level for the specific volcano before you travel, not the region. Levels change with little notice, and a track that was open when you planned the trip may be closed by the time you arrive.",["Check GeoNet for the specific volcano","Level 2 and up closes tracks","Levels change with little notice"]),s("The Tongariro Alpine Crossing passes active vents","The Crossing runs close to Te Maari and the Red Crater area, and the route includes signed sections where you should not linger. Eruptions here have happened with no useful warning, including in 2012 when the track was damaged.","Follow the signage, do not stop for long in the marked hazard zones, and be prepared to turn back. The Crossing is also frequently closed or unsafe for weather reasons entirely separate from volcanic risk."),s("Geothermal ground is thinner than it looks","Around Rotorua, Taupō and Waiotapu the crust over boiling mud and water can be thin, and people have been very seriously injured stepping off marked paths. Ground that looks solid and dry can give way, and the water beneath is well above boiling.","Stay on the boardwalks and behind the barriers without exception, keep children in hand, and do not enter unmarked thermal areas even where there is no fence. Hydrogen sulphide also collects in hollows and can reach harmful concentrations.",["Never step off the boardwalk","Thin crust over boiling water","Gas collects in hollows"]),s("Ashfall and what it does","Volcanic ash is abrasive glass rather than soft soot. It damages engines and air filters, blocks windscreen washers and makes roads slippery, and it is a genuine respiratory irritant. Even light ashfall can close roads and airports at short notice.","If ashfall occurs, stay indoors or in the vehicle with vents closed, wear a proper mask rather than a cloth one if you must be outside, and do not drive unless necessary. Wetting ash before removing it stops it becoming airborne again."),{heading:"Understanding the risk honestly",body:["New Zealand's active volcanoes are closely monitored and the alert system is genuinely informative, but eruptions here have occurred with little or no useful warning. Whakaari in 2019 and Te Maari in 2012 both showed that unrest levels do not reliably predict short-term events.","That does not mean avoiding the central plateau. It means treating access restrictions as absolute, staying within signed areas, and accepting that a track closure is not a formality to be worked around.","Ruapehu also carries lahar risk in valleys draining the crater lake, which is why signage tells you not to linger in stream beds. Crossing quickly rather than stopping for a photograph is the entire requirement."]},s("Travel disruption from ash","Ash closes airspace quickly and flights can be grounded for days, which matters more to most travellers than direct volcanic hazard. A significant Ruapehu or Taranaki event would disrupt domestic aviation across the country.","Keep a buffer before an international departure and travel insurance that covers natural disaster disruption. Neither is expensive and both are the practical response to volcanic risk here.",["Ash closes airspace for days","Buffer before international flights","Check insurance covers disruption"])],sources:[{label:"GeoNet volcanic activity",url:"https://www.geonet.org.nz/volcano"},{label:"DOC Tongariro National Park alerts",url:"https://www.doc.govt.nz/parks-and-recreation/places-to-go/central-north-island/places/tongariro-national-park/"}]}),
  a({slug:"river-crossing-safety-new-zealand",title:"River crossing safety for New Zealand tracks and camps",description:"Rain upstream can turn a familiar ford into a barrier, and turning back is often the only safe technique.",category:"Rules & safety",region:"New Zealand rivers",places:["West Coast","Fiordland","Canterbury rivers","Backcountry tracks"],imageAlt:"Fast New Zealand river crossing a backcountry route",intro:"Rivers cause serious backcountry incidents because depth, speed and bed stability are hard to judge from the bank. A planned turnaround point is more valuable than a memorised crossing manoeuvre.",sections:[s("Assess before entering","Check the forecast, recent rain and route advice before departure. Look for rising or discoloured water, moving debris, a strong current and no safe exit.","If the river is in flood, wait or turn back. Do not enter to test the depth and never cross merely because another group has started."),s("Use expertise honestly","River-crossing skills require practical instruction and good group judgement. Unbuckle pack straps where trained guidance recommends it and avoid linking up in ways the group has not practised.","Choose bridges or marked alternatives when available. A longer route is the correct route when the ford is doubtful."),s("Vehicle fords are hazards too","Know the manufacturer's wading limits and the road authority's closure status. Water can hide washouts and push a vehicle sideways at surprisingly low depth.","Never drive around a flood barrier. Park well back, wait for official reopening and keep enough food and fuel for the delay." ),s("River crossings kill trampers here every year","New Zealand rivers rise fast, run cold and carry more force than they appear to. Drowning during crossings has historically been common enough to be described as the New Zealand death, and almost all of it involves people who decided to cross when they should have waited.","The decision is the skill. Turning back or waiting is always available and always safe; the crossing is not. If there is any doubt, there is no doubt.",["If in doubt, do not cross","Waiting is always the safe option","Most incidents are decision failures"]),s("Reading whether it is crossable","Look for a wide, straight, shallow reach with an even bed and a safe run-out below rather than rapids, logjams or a deep pool. Discoloured water, debris moving downstream, a rumbling sound of boulders and water above knee height on the shortest party member are all reasons not to cross.","Never cross where you cannot see the bottom, and never immediately above a hazard. Rivers change with every flood, so a crossing point described in an old guide may no longer exist."),s("If you do cross","Undo the waist belt and chest strap on your pack so it can be shed, keep boots on for grip, and face upstream slightly while moving across and downstream at an angle. Move one foot at a time and keep both feet planted before shifting weight.","Cross as a linked group where possible, with the strongest members on the upstream and downstream ends, and move together. If someone is swept away, they should go feet first on their back and swim for the bank at an angle rather than fighting the current.",["Undo pack straps before entering","Link up and move together","Feet first on your back if swept"]),s("Wait it out","Most New Zealand rivers drop as quickly as they rise, frequently within hours of the rain stopping. Carrying an extra day of food turns a dangerous decision into an inconvenient wait, which is why the standard advice is to plan for one.","Tell someone your intentions before you go so an overdue party triggers a response, and carry a personal locator beacon on any route with crossings. Both are cheap compared with the alternative."),{heading:"Alternatives to crossing",body:["Check whether a bridge exists upstream or downstream before committing, because many tracks have one within a reasonable distance and the detour is almost always shorter than the consequences of getting a crossing wrong.","Many New Zealand backcountry routes are unbridged by design, and the route description usually says whether crossings are expected. Where it does, treat that as a requirement for the skills and the willingness to wait rather than as a passing note.","Waiting is the most underused option available. Most rivers here drop within hours of the rain stopping, and carrying an extra day of food converts a dangerous decision into an inconvenient afternoon."]},s("Learning before you need it","River crossing is a taught skill and reading about it is not the same as having practised. Outdoor clubs, guiding companies and some DOC visitor centres run or can point you towards training, and it is worth doing before a trip with crossings on it.","If nobody in the party has crossed a river before, choose a route that does not require it. There are plenty of excellent multi-day walks in New Zealand with bridged crossings throughout.",["Crossing is a taught skill","Choose bridged routes if untrained","Reading about it is not practice"])],sources:[{label:"DOC river safety",url:"https://www.doc.govt.nz/parks-and-recreation/know-before-you-go/safety-in-the-outdoors/river-crossing/"}]}),
  a({slug:"winter-driving-new-zealand-campervan",title:"Winter driving in a New Zealand campervan",description:"Snow chains, black ice, wind and a high-sided vehicle require slower days and practised equipment.",category:"Rules & safety",region:"New Zealand alpine roads",places:["Crown Range","Arthur's Pass","Lindis Pass","Desert Road","Milford Road"],imageAlt:"Campervan driving on a snowy New Zealand road",intro:"A campervan carries more side area, weight and stopping distance than the car many visitors drive at home. Winter adds conditions that make a legal speed entirely unsuitable.",sections:[s("Check the whole route","Read Waka Kotahi road status, MetService warnings and local chain-control information before departure. Recheck at the last town where waiting is comfortable.","Passes can be open while shaded approaches remain icy. Delay the drive until light and temperature improve."),s("Know the chains","Carry chains that fit the driven wheels and practise installation before the trip. Follow signs and authority directions about when and where they are required.","Use a safe fitting area, gloves and a torch. Never stop in a live lane or at the exact point where every unprepared driver has already queued."),s("Drive the vehicle you have","Accelerate, steer and brake gently, increase following distance and use lower gears on descents. Strong crosswinds can require a delay even without snow.","If confidence or visibility fails, turn back or use a legal stop. Rental schedules and prepaid camps do not reduce the physics." ),s("Chains: carry, know, practise","Chain fitting is required at times on the Milford road, the Crown Range, the Lindis, Arthur's Pass, the Desert Road and others, and some rental agreements require you to carry them for the whole winter trip regardless of route. Enforcement at control points is real.","Fit them once at home, in daylight, on dry ground, so the first attempt is not in sleet on a narrow shoulder with traffic going past. That first attempt in bad conditions is where people give up and press on unequipped instead.",["Practise fitting in the dry first","Some rentals require carrying them always","Control points do enforce"]),s("Black ice","Black ice forms where the road merely looks wet, particularly in shade, on bridges and in the first and last hours of daylight. It gives no warning and no grip, and the instinctive responses of braking hard or steering sharply are both wrong.","Slow down before shaded sections rather than in them, increase following distance well beyond your summer habit, and if you do feel the vehicle go light, come off the accelerator gently and steer where you want to go without sudden input."),s("A campervan handles differently in winter","A high-sided vehicle is affected by crosswind far more than a car, and on a wet or icy road that combination is the one that puts vehicles off the edge. Its braking distance is longer, its centre of gravity higher, and it is heavier than it feels.","Slow down well before corners rather than during them, avoid sudden steering, and treat the posted limit as a maximum for perfect conditions rather than a target. Check tyre tread and pressures before the trip, because winter finds a marginal tyre quickly.",["Crosswind affects high-sided vans badly","Brake before the corner, not in it","Check tread and pressures before leaving"]),s("Shorter days, shorter plans","Midwinter gives roughly nine hours of usable light in the south, and a valley loses the sun well before official sunset. Driving legs that work in February become uncomfortable and then unsafe in July, so plan shorter days rather than earlier starts in the dark.","Check NZTA road conditions each morning, and treat a closure as a reason to reroute or stop rather than to wait indefinitely. Carry extra food, water, warm layers and charge, because a closure can hold you for hours."),{heading:"Before you set out each morning",body:["Check road conditions for every pass on the day's route on the morning itself, because closures and chain requirements are decided early. Then check the forecast for the pass rather than for the towns at either end, which can be completely different.","Clear all snow and ice off the vehicle including the roof before moving. Snow sliding off a roof onto your own windscreen at speed is a real hazard, and so is it landing on the vehicle behind you.","Refuel at half a tank rather than a quarter in winter. A closure can hold you for hours with the engine running for heat, and being low on fuel while stationary in the cold is a genuinely poor position to be in."]},s("Where to stay in winter","Many DOC campsites close or turn off water over winter and small-town holiday parks reduce hours. Powered sites become considerably more valuable when you need heating overnight, and they book up around ski fields.","Base yourself in a town rather than remote sites when the forecast is poor. Being able to walk to food and warmth changes a bad-weather day from an ordeal into an ordinary one.",["Many DOC sites close for winter","Powered sites matter more in cold","Ski town parks book out"])],sources:[nztaVisitors]}),
  a({slug:"new-zealand-road-signs-visitors",title:"New Zealand road signs visitors should understand",description:"Regulatory, warning and temporary signs must be read together with road markings and conditions.",category:"Rules & safety",region:"New Zealand roads",places:["One-lane bridges","Advisory speeds","Rail crossings","Temporary traffic controls"],imageAlt:"New Zealand one-lane bridge warning sign",intro:"New Zealand signs use familiar international ideas but local road situations can surprise visitors. One-lane bridge priority, advisory corner speeds and temporary controls need recognition before the road narrows.",sections:[s("Limits and advisory numbers","A red-ring speed sign sets the maximum legal speed; a yellow advisory number indicates a safer corner speed rather than a new limit. Conditions can require travelling below both.","Temporary orange signs and portable limits are enforceable where installed. Continue obeying them until the end of the work zone."),s("One-lane bridges","A red-bordered give-way sign means traffic from your direction must yield. A blue rectangular priority sign gives your direction priority, but only when the bridge is clear and safe to enter.","Check for long or heavy vehicles already committed and never race another driver to the entrance."),s("Rail and rural hazards","Stop or give way at railway controls as signed, look both ways and never queue across tracks. Rural warning signs also identify stock, slips, ice and winding roads.","Learn the official visitor-driving material before collecting a rental. Navigation prompts do not explain the meaning of a roadside instruction." ),s("Give Way rules at intersections","New Zealand's give way rules changed in 2012 and older overseas guidance is wrong. The current position is that at an uncontrolled intersection or when both vehicles face the same control, a turning vehicle gives way to a vehicle going straight through or turning left.","Roundabouts run clockwise and you give way to traffic on your right. Signal left as you leave, and take particular care on multi-lane roundabouts where lane markings determine which exit you may take.",["Turning gives way to straight-through","Roundabouts run clockwise","Give way to your right"]),s("One-lane bridge signage","One-lane bridges are common, particularly on the West Coast and in Northland. The sign shows two arrows: the larger black arrow indicates the direction with priority. If your arrow is the smaller red one, you give way to oncoming traffic.","Some bridges are shared with rail, and a few are long enough to include passing bays. Slow on approach, look right through the bridge before entering, and be willing to wait rather than racing to claim it."),s("Advisory speeds and hazard warnings","Yellow diamond signs are warnings rather than legal limits, and the yellow speed shown on a corner is an advisory maximum for a car in good conditions. In a loaded campervan, in rain, or towing, the safe speed is lower than the advisory figure.","Watch for the signs specific to New Zealand conditions: slippery when wet, loose metal, ford, stock crossing and the falling rocks warning used widely on the West Coast and through the passes.",["Yellow signs are advisory, not legal","Advisory speeds assume a car in the dry","Loose metal means gravel"]),s("Passing lanes and slow vehicle bays","Passing lanes are infrequent on New Zealand highways, and the courteous and expected behaviour if you are slower than the traffic behind is to use the slow vehicle bay or pull over where safe and let them pass. This is more than politeness; frustrated following drivers cause overtaking crashes.","Do not accelerate in a passing lane when someone is overtaking you. If five or more vehicles are queued behind you, you are legally required to pull over as soon as it is safe to do so."),{heading:"Signs specific to New Zealand",body:["LSZ marks a Limited Speed Zone on some rural roads, where the limit drops when conditions require it. A Ford sign means the road crosses a watercourse, which may be dry or impassable depending on recent rain.","Stock crossing and stock effluent signs indicate active farming use of the road. Slippery when wet appears widely on sealed rural roads where the chip seal becomes genuinely slick, and it is worth taking seriously in a heavy vehicle.","Blue and white signs mark tourist routes and services while brown signs indicate historic and cultural sites. Neither implies the road beyond is suitable for a large vehicle, so check that separately before turning off."]},s("Roadworks and stop-go","Temporary works are frequent, particularly after winter damage, and a stop-go operator directing traffic has legal authority. Wait for the signal rather than following the vehicle in front through a closing gap.","Temporary limits apply whether or not work is visibly happening, including overnight and at weekends. The surface through works is often loose chip, which is genuinely slippery for a heavy vehicle.",["Stop-go operators have legal authority","Temporary limits apply at all hours","Loose chip is slippery"])],sources:[{label:"NZTA road code signs",url:"https://www.nzta.govt.nz/roadcode/general-road-code/about-driving/signs-and-markings/"}]}),
  a({slug:"overseas-driver-licence-new-zealand",title:"Driving in New Zealand with an overseas licence",description:"Validity, translations, time limits and vehicle weight all need checking before the rental handover.",category:"Rules & safety",region:"New Zealand",places:["Overseas licence","English translation","International Driving Permit","Class 1 vehicle"],imageAlt:"Visitor checking an overseas licence beside a campervan",intro:"A current overseas licence can allow visitor driving, but the document language, time since entry, licence conditions and campervan weight determine whether that permission applies.",sections:[s("Current 2026 time limits","As of August 2026, an eligible overseas car licence can be used for up to 18 months from the last arrival. From 1 November 2026, that car-licence period reduces to 12 months.","Overseas motorcycle and truck licence limits differ. Anyone staying across the change should check NZTA for the rule on the actual driving date."),s("Translation and documents","A licence not in English needs an accurate approved translation or qualifying International Driving Permit, carried with the original current licence.","An IDP supports the original licence; it does not revive an expired, suspended or invalid document."),s("Vehicle class and conditions","A full overseas car licence generally aligns with New Zealand Class 1 up to 6,000 kg gross laden weight, subject to any lower home-licence limit. Larger motorhomes can require a different class.","Rental acceptance and insurance do not override licensing law. Confirm legal authority, contract and cover separately." ),s("What you can drive on and for how long","You may drive on a current overseas licence for up to twelve months from your date of arrival, provided the licence is valid, you have not been disqualified, and you drive only the vehicle classes it covers. After twelve months you must convert to a New Zealand licence.","The licence must be in English or accompanied by an accurate translation, or an International Driving Permit. Carry the original licence at all times; an IDP supports it and does not replace it.",["Twelve months from date of arrival","Carry the original licence, not just an IDP","Translation required if not in English"]),s("Vehicle class matters for campervans","A standard car licence covers vehicles up to 6,000 kg gross laden weight in New Zealand, which is more generous than several other countries and covers most rental campervans. Larger motorhomes may fall outside it, and your home licence class is what determines the equivalence.","Rental companies apply their own age and licence conditions on top of the law, frequently requiring a minimum age and a licence held for a minimum period. Permission from a rental company does not override licensing law, and licensing law does not override the rental terms."),s("Restrictions carried from your home licence","Any condition on your original licence applies here: corrective lenses, automatic transmission only, an alcohol interlock, or a restricted class. Driving outside those conditions is driving unlicensed, with the insurance consequences that follow.","A restricted or probationary licence from another country generally carries its restrictions with it. If you are on a graduated licence at home, check what that means before assuming you can drive freely here.",["Home licence conditions still apply","Automatic-only means automatic-only","Graduated licences carry restrictions"]),s("Insurance and the excess","Third party injury is covered for everyone by ACC regardless of fault, which is unusual and means you cannot sue for personal injury from a crash. Vehicle damage is not covered by that, and rental excess amounts here are frequently high.","Read what the excess reduction actually covers, because windscreen, tyres, undercarriage, water damage and single-vehicle accidents are commonly excluded even from reduced-excess products. Those are also the most likely things to happen on New Zealand roads."),{heading:"Converting to a New Zealand licence",body:["After twelve months you must convert. Drivers from a list of recognised countries can convert without sitting theory or practical tests, while others must pass both. The list changes, so check the current position rather than relying on secondhand information.","Conversion requires proof of identity, your overseas licence, an eyesight check and a fee, and is handled through a licensing agent. Allow time, because the process is not instant and driving on an expired entitlement is an offence.","If you are staying long term and your country is not recognised, start early. Booking a practical test can take several weeks in the main centres, and the wait is longer again over summer."]},s("Renting with an overseas licence","Rental companies impose their own conditions beyond the law: a minimum age, a licence held for a minimum period, and sometimes a young-driver surcharge. Some decline licences from particular countries or require an International Driving Permit regardless.","Confirm these when booking rather than at the counter. Arriving at a depot and being refused the vehicle is a genuinely difficult problem to solve at an airport.",["Minimum age and licence-held periods apply","Some companies require an IDP regardless","Confirm at booking, not at pickup"])],sources:[nztaVisitors]}),
  a({slug:"campervan-road-rules-new-zealand",title:"Campervan driving rules and safety in New Zealand",description:"Dimensions, passengers, weight and rental restrictions matter before a narrow road exposes the vehicle's size.",category:"Rules & safety",region:"New Zealand roads",places:["Rental depot","Narrow bridges","Gravel roads","Low clearances"],imageAlt:"Large campervan on a narrow New Zealand road",intro:"A campervan can be legal on a Class 1 licence and still feel completely different from a car. The handover should establish height, width, length, loaded weight and every road excluded by the rental agreement.",sections:[s("Measure before moving","Record the vehicle dimensions where the driver can see them. Roof vents, air-conditioning units, bike racks and rear overhang affect clearances and manoeuvring.","All passengers need approved seats and restraints while travelling. Beds and rear living areas are not passenger positions unless certified as such."),s("Give the vehicle room","Brake earlier, take corners slowly and leave a larger following gap. Use mirrors deliberately and let following traffic pass at safe formed areas.","Strong crosswind can move a tall vehicle across the lane. Reduce speed or stop when steering corrections become constant."),s("Respect exclusions","Rental contracts may prohibit beaches, unsealed roads or named remote routes even when public access exists. Insurance can depend on the same conditions.","Stop before a low branch, weight-restricted bridge or uncertain ford. Vehicle recovery is not a substitute for clearance." ),s("Know your dimensions before you drive off","Write down the height, length and weight of the vehicle and keep it where the driver can see it. Height is the one that causes expensive damage, on car park entrances, drive-throughs, service station canopies and a number of urban underpasses.","Check the mirrors, blind spots and reversing camera before leaving the depot, and walk the vehicle. Most rental campervan damage happens in the first two days, at low speed, in car parks.",["Write the height on the dashboard","Most damage happens in car parks","Walk the vehicle before you leave"]),s("Everyone travels in a proper seat","Beds, dinettes without belts and living areas are not passenger positions while the vehicle is moving. Every occupant needs an approved seat with a working belt, and child restraints are required for under-sevens with specific standards applying.","Secure everything loose before every drive. A cupboard door, a gas bottle or a full kettle becomes dangerous under emergency braking, and campervans brake later and harder than a car."),s("Wind, and why it matters more here","A high-sided vehicle catches crosswind badly, and New Zealand is a windy country with exposed coastal roads, bridges and mountain gaps. Overtaking trucks and emerging from cuttings both produce sudden lateral shoves.","Hold the wheel firmly with both hands in exposed sections, slow down before rather than during a gust, and be aware that some routes close to high-sided vehicles in strong wind, including the Rimutaka Hill Road and parts of the Desert Road.",["Slow before the exposed section","Some roads close to high-sided vehicles","Trucks and cuttings cause sudden gusts"]),s("Overtaking and being overtaken","A campervan accelerates slowly, so overtaking requires far more clear road than a car needs and is rarely worth attempting. Most of New Zealand's highways are two-lane with limited passing lanes and a poor overtaking crash record.","When traffic builds behind you, pull over where safe and let it past. If five or more vehicles are queued behind you, you are required to do so as soon as it is safe, and it also removes the pressure that causes people to overtake badly."),{heading:"Parking and overnight legality",body:["Parking a campervan is a different question from camping in it. A vehicle can be legally parked somewhere and still be prohibited from being occupied overnight, and that distinction is what most infringements actually turn on.","Height restrictions in urban car parks catch campervans out constantly, and the barrier is usually the first indication. Look for signed height limits before entering, and use the surface or overflow parking most towns provide for larger vehicles.","In cities the practical approach is to leave the vehicle at a campground or park-and-ride and take public transport in. It is faster, cheaper and avoids the entire problem rather than managing it."]},s("Ferries, tunnels and height limits","Cook Strait fares are set by vehicle length and height, and both are checked. Some urban tunnels and older bridges carry height or weight restrictions, and a few routes are closed to high-sided vehicles in strong wind.","Know your dimensions precisely and check them against any route with a tunnel, a low bridge or a ferry booking. Guessing is what produces an expensive adjustment at a terminal or worse on a road.",["Ferry fares are set by size","Know exact height and length","Some routes close to high-sided vans"])],sources:[nztaVisitors]}),
  a({slug:"wof-registration-campervan-new-zealand",title:"Warrant of Fitness, registration and rental campervans",description:"A current sticker is only one part of proving that a vehicle can lawfully use the road.",category:"Rules & safety",region:"New Zealand vehicles",places:["Warrant of Fitness","Certificate of Fitness","Vehicle licence","Rental agreement"],imageAlt:"New Zealand vehicle inspection and registration labels",intro:"Light campervans generally need a current Warrant of Fitness and vehicle licence, while heavier or passenger-service vehicles can operate under different inspection systems. Check the exact vehicle rather than assuming the rental category answers it.",sections:[s("Read the labels","Confirm the inspection and licensing expiry dates before departure. A WoF checks specified safety items at the inspection date; it is not a guarantee against later mechanical failure.","Ask the operator to explain any Certificate of Fitness or road-user-charge display relevant to the vehicle."),s("Driver checks still matter","Inspect tyres, lights, mirrors, windscreen, fluids and warning lamps. Report damage before leaving the depot and photograph the agreed condition.","Secure cupboards, gas bottles, tables and loose gear. A legal vehicle can still become unsafe when the living space is not prepared for motion."),s("When something changes","Stop safely for a warning light, tyre issue or new vibration. Contact the rental or roadside provider before continuing in a way that may worsen damage.","Do not alter seats, plumbing, gas or structural fittings without qualified approval. Modifications can affect inspection, certification and insurance." ),s("What a WoF actually covers","A Warrant of Fitness is a periodic safety inspection covering brakes, tyres, lights, steering, structure and glazing. It is a snapshot on the day of inspection rather than a guarantee of condition, and the legal responsibility to keep the vehicle roadworthy sits with the driver at all times.","Driving a vehicle with an expired WoF is an offence and can void insurance. Check the label on the windscreen when you collect a rental, and check that the expiry covers your entire hire period rather than just the pickup date.",["Check the expiry covers your whole hire","A WoF is a snapshot, not a guarantee","Expired WoF can void insurance"]),s("Registration and road user charges","Vehicle licensing, commonly called rego, must be current and is displayed on the windscreen. Diesel vehicles additionally require road user charges purchased in advance per thousand kilometres, and running past the distance purchased carries a penalty.","For a rental, ask whether RUC is included in the daily rate or billed separately at the end, because on a long trip in a diesel campervan it is a meaningful amount that can arrive as an unexpected charge."),s("Self-containment is a separate certificate","Self-containment certification is not part of a WoF and proves nothing about roadworthiness. Equally, a current WoF says nothing about whether a vehicle may be used for freedom camping. They are independent requirements and you may need both.","Check the self-containment warrant against the vehicle registration on the public register rather than trusting the sticker, and confirm the certified occupancy matches your party.",["WoF and self-containment are unrelated","Check the plate on the SCV register","Confirm certified occupancy"]),s("Checks worth doing yourself","Before a long leg, check tyre pressures and tread including the spare, the oil and coolant levels, the lights and the windscreen washers. Rental campervans are frequently handed over with underinflated tyres, which costs fuel and handling at once.","Confirm the spare, jack and wheel brace are actually present and that you know where the jacking points are. Discovering they are missing on a gravel road on the West Coast is a considerably worse time to find out."),{heading:"If something goes wrong on the road",body:["Rental agreements set out who to call and what you may arrange yourself. Getting repairs done without approval frequently voids reimbursement, so call first even when the fix seems obvious and the delay is irritating.","For a breakdown in a remote area, stay with the vehicle. It is shelter, it is far easier for rescuers to spot than a person walking, and on many South Island roads walking out is considerably worse than waiting.","Carry the roadside assistance number written down rather than only in a phone, and be able to describe where you are. A road name and the nearest identifiable landmark is usually enough for a tow operator to find you."]},s("Returning the vehicle","Most disputes at return are about cleanliness, fuel level, tank emptying and undeclared damage. Photograph the vehicle inside and out at pickup and again at return, with the odometer and fuel gauge visible.","Empty and rinse the waste tanks before returning, because cleaning charges are high and easily avoided. Read what condition the agreement requires rather than assuming a reasonable standard.",["Photograph at pickup and return","Empty tanks before returning","Cleaning charges are steep"])],sources:[{label:"NZTA vehicle licensing and WoF",url:"https://www.nzta.govt.nz/vehicles/warrants-and-certificates/"}]}),
  a({slug:"towing-caravan-new-zealand",title:"Towing a caravan in New Zealand",description:"The 90 km/h maximum, loaded weights and four-second gap are starting points, not targets.",category:"Rules & safety",region:"New Zealand roads",places:["Caravan","Light trailer","Tow vehicle","Open road"],imageAlt:"Car towing a caravan on a New Zealand highway",intro:"A stable caravan depends on the legal combination, correct loading and a driver who slows before the road demands it. New Zealand's curves and wind make the maximum permitted speed irrelevant on many sections.",sections:[s("Know the combination","Check the tow rating, coupling, safety chain, lights, tyres, brakes and loaded weights for both vehicles. Account for water, gas, bikes and equipment added after the empty specification.","Passengers cannot travel inside a caravan on the road. Everyone belongs in an approved restrained seat in the tow vehicle."),s("Speed and spacing","The maximum open-road speed while towing is 90 km/h with a rigid connection. Travel slower whenever stability, visibility, weather or the road requires it.","Leave at least a four-second gap, with more in bad weather. Brake before corners and select a lower gear for descents."),s("Share narrow roads","Use safe pull-over areas to let following traffic pass and approach one-lane bridges only when the full combination can clear.","Strong wind, trailer sway or hot brakes require a stop. Do not attempt to recover lost itinerary time by increasing speed." ),s("Towing speed limits are lower","Light trailers and caravans are limited to 90 km/h on the open road, below the 100 km/h general limit, and heavy trailer combinations are also capped at 90 km/h. The limit applies regardless of the posted speed, and it is enforced.","Leave a much larger following gap than you would in a car. Braking distance increases substantially with a trailer, and the most common towing crashes here involve running out of stopping room on a descent.",["90 km/h maximum when towing","Braking distance increases sharply","Bigger following gap than a car"]),s("Weights, ratings and loading","The tow vehicle's maximum towing capacity, the towbar rating, the caravan's gross laden weight and the tow ball download all have to agree, and the limiting figure is whichever is lowest. Exceeding any of them affects handling, braking and insurance.","Load heavy items low and over the axle, keep roughly ten percent of the weight on the tow ball, and avoid loading the rear of the caravan, which is what causes sway. Check the load again after the first hour of driving."),s("Sway and how to respond","Sway usually starts from a crosswind gust, a passing truck or too little tow ball weight, and it builds rather than settling. The instinct to brake hard or steer against it makes it worse.","Ease off the accelerator gently, keep the steering straight, and let the combination slow itself. If your vehicle has a trailer brake controller, applying the trailer brakes alone can pull the combination straight. Then stop and check the loading.",["Ease off, do not brake hard","Keep the steering straight","Stop and recheck the load after"]),s("Roads to think twice about","Tākaka Hill, the Crown Range, the Rimutaka Hill Road, the 309 Road and much of the Coromandel coast are demanding with a caravan and some are prohibited or strongly discouraged for large combinations. Check before committing, since turning around is often not possible.","On descents, select a lower gear and use engine braking rather than riding the brakes, which fade. Pull over regularly to let following traffic past, both as courtesy and because a queue behind you creates overtaking risk."),{heading:"Reversing, parking and campgrounds",body:["Practise reversing in an empty car park before the trip. Campground sites frequently require a reverse into a defined space with neighbours close on both sides, and doing that for the first time with an audience is how people damage vans.","Book sites that suit your combination length and say you are towing when you book. Many holiday parks keep specific drive-through sites, and getting one removes most of the difficulty from arrival.","Unhitching gives you an ordinary vehicle for day trips and is worth doing whenever you stay more than one night. Use wheel chocks and levelling ramps, and check the handbrake holds before disconnecting anything."]},s("Wind and exposed roads","A caravan is a large flat surface and crosswind is the main cause of loss of control while towing. Exposed sections around Wellington, the Desert Road, the Mackenzie and coastal Canterbury are all known for it.","Slow down before exposed sections rather than reacting within them, and take particular care when emerging from a cutting or passing a truck, where the wind loads and unloads suddenly.",["Crosswind is the main towing hazard","Slow before exposed sections","Trucks cause sudden gusts"])],sources:[{label:"NZTA motorhomes, caravans and light trailers",url:"https://nzta.govt.nz/vehicles/vehicle-types/motorhomes-caravans-light-trailers"}]}),
  a({slug:"speed-limits-new-zealand-visitors",title:"Speed limits and safe pace on New Zealand roads",description:"The posted number is a ceiling in good conditions, while many rural roads demand much less.",category:"Rules & safety",region:"New Zealand roads",places:["Urban roads","Open roads","School zones","Roadworks"],imageAlt:"New Zealand speed limit sign on a rural road",intro:"A legal limit is not a promise that a road can be driven at that speed. Corners, rain, gravel, stock, cyclists and an unfamiliar campervan all reduce the safe pace.",sections:[s("Read each change","Speed limits vary by road and location, with temporary limits at works and lower zones around many communities or schools. Watch signs rather than relying on a remembered national default.","A yellow advisory speed before a corner is not the legal limit, but it communicates road geometry that deserves attention."),s("Slow before the hazard","Brake on the straight before entering a curve and keep enough margin to stop within the visible road. Gravel and wet leaves reduce grip well before a warning appears.","At night or in fog, reduce speed until the headlights reveal enough stopping distance. High beams cannot solve a winding road."),s("Do not create pressure","Let faster traffic pass at safe formed areas. Never speed up on a passing lane only to hold a queue again at the next bend.","If the planned arrival depends on driving at every posted maximum, the itinerary is already too tight." ),s("The posted limit is a maximum, not a target","The open road limit is generally 100 km/h and urban areas are usually 50 km/h, with variable and reduced limits around schools, roadworks and some rural highways. The limit assumes ideal conditions, a car, and a driver familiar with the road.","Almost no New Zealand rural highway is comfortable at 100 km/h in a loaded campervan, in rain, or on an unfamiliar winding section. Driving at a speed that suits the conditions is both legal and expected, and driving too slowly on a straight is not the same thing as driving safely.",["100 km/h open road, 50 urban","Limits assume ideal conditions","Towing is capped at 90 km/h"]),s("Enforcement is tighter than many visitors expect","The tolerance is small, speed cameras are widespread including mobile units, and fines are issued to the registered keeper, which means a rental company will pass them on with an administration fee. Points do not apply to overseas licences but fines certainly do.","Average speed enforcement and lower rural limits have both expanded in recent years. Assume any road may be monitored rather than looking for cameras."),s("Why the roads themselves demand less speed","New Zealand highways are largely two-lane, undivided, with tight radii, variable camber, one-lane bridges, unfenced stock and frequent unsealed side roads throwing gravel onto the surface. There is very little forgiving shoulder.","That combination is why crash rates involving visiting drivers are concentrated on rural roads. The safe pace is usually well below the limit, and the time lost across a day is a few minutes rather than the hour people imagine.",["Two-lane, undivided, little shoulder","Gravel gets thrown onto sealed roads","Driving slower costs minutes, not hours"]),s("Speed and the passing lane","Do not increase speed when a passing lane appears and someone is overtaking you. It is the most common source of conflict on New Zealand highways and it turns a safe overtake into a dangerous one.","Equally, if you are being followed closely, do not feel pressured to exceed a speed you are comfortable with. Use the next slow vehicle bay or safe pull-off and let them go; the pressure disappears and so does the risk."),{heading:"Variable and reduced limits",body:["Limits around schools drop at set times and are signed with flashing or variable displays. Roadworks carry temporary limits that apply whether or not anyone is visibly working, and they are enforced with the same small tolerance as permanent limits.","A number of rural highways have had limits reduced from 100 km/h following safety reviews, and the change is not always obvious if you are working from an older map or a previous visit. Read the signs rather than assuming the open road limit applies.","On unsealed roads the posted limit is frequently still 100 km/h, which is nowhere near a safe speed on gravel. Here the limit is genuinely a legal maximum rather than any indication of what the surface supports."]},s("How speed cameras and fines work","Fixed and mobile cameras operate throughout the country and the enforcement tolerance is small. Fines are issued to the registered keeper, so a rental company receives them and passes them on with an administration fee.","Demerit points do not apply to an overseas licence but the fines do, and unpaid infringements can follow you. Pay them rather than assuming they disappear when you leave.",["Small enforcement tolerance","Rentals add an admin fee","Unpaid fines follow you"])],sources:[{label:"NZTA speed limits",url:"https://www.nzta.govt.nz/roadcode/general-road-code/about-limits/speed-limits/"}]}),
  a({slug:"alcohol-fatigue-driving-new-zealand",title:"Alcohol, fatigue and visitor driving in New Zealand",description:"A legal alcohol threshold is not a safety target, and jet lag can impair the first drive before the road trip begins.",category:"Rules & safety",region:"New Zealand roads",places:["Airport arrivals","Rural highways","Rest areas","Holiday parks"],imageAlt:"Driver resting beside a campervan before continuing",intro:"Visitors often combine a long flight, an unfamiliar vehicle and left-side driving on the same day. Treat rest as part of the booking and keep alcohol completely separate from any driving responsibility.",sections:[s("Rest after the flight","Book a nearby first night or use depot transport rather than starting a major drive jet-lagged. Learn controls, mirrors and vehicle size in daylight.","Fatigue signs include repeated yawning, wandering attention and missed signs. Stop at the first warning rather than bargaining for the next town."),s("Alcohol rules vary by driver","Drivers under 20 must have zero alcohol. Other legal limits and penalties do not establish a safe personal amount, especially with fatigue, medication or an unfamiliar road.","Nominate a sober driver or leave the vehicle parked. Coffee, food and a short wait do not rapidly remove alcohol."),s("Build real breaks","Change drivers where both are licensed and insured, stop for movement and avoid long night sections. Rest areas are for safe breaks, not automatically legal camping.","Plan the campsite before fatigue peaks. A booked nearby holiday park is cheaper than a crash, infringement or damaged vehicle." ),s("The legal limits","For drivers aged 20 and over the limit is 250 micrograms of alcohol per litre of breath, or 50 milligrams per 100 millilitres of blood. For drivers under 20 the limit is zero. Both are enforced through frequent checkpoints, including on rural roads and during the day.","There is no reliable way to estimate your own level, and the standard drink calculations circulating online do not account for body composition, food, fatigue or the previous evening. The only safe approach on a road trip is to separate drinking from driving completely.",["Zero limit under 20","250 mcg breath, 50 mg blood over 20","Checkpoints are common and random"]),s("Morning-after driving","This is where visitors most often get caught. Alcohol clears at roughly one standard drink an hour and no faster, so a heavy evening can leave you over the limit well into the following morning. Sleep, coffee and a shower do nothing to speed it up.","On a camping trip the vehicle is right there and the temptation to move early is strong. If you drank substantially, plan to leave late rather than early, and build that into the itinerary rather than deciding at 7am."),s("Fatigue is the larger risk on this trip","Long-haul flight arrival, jet lag, an unfamiliar vehicle, driving on the other side and winding roads combine badly, and fatigue is a factor in a substantial share of visitor crashes here. The first 48 hours after arrival are the highest risk period of the whole trip.","Do not collect a campervan and drive for four hours on arrival day. Stay near the airport the first night, take the first driving day short, and swap drivers regularly if you can.",["Do not drive far on arrival day","First 48 hours are highest risk","Swap drivers every two hours"]),s("Recognising it before it matters","Yawning, heavy eyes, drifting in the lane, missing a turn, and having no memory of the last few kilometres are all late signs rather than early ones. By the time you notice them, reaction time is already substantially impaired.","Stop every two hours as a rule rather than when you feel tired. A twenty minute nap is genuinely effective; music, fresh air, energy drinks and conversation are not, and they mainly mask the symptoms while the impairment continues."),{heading:"Planning a trip that avoids the problem",body:["Build wine region visits around a designated driver, a bicycle or a tour rather than intending to be careful. Marlborough, Hawke's Bay, Central Otago and Martinborough are all compact enough that cycling between cellar doors is the normal approach.","Where you plan to drink, plan to stay. Booking the campground at the place you are drinking rather than half an hour away removes the decision entirely, and it usually costs the same.","On fatigue, build the itinerary so no day needs more than about four hours of driving, and put the shortest day immediately after your international arrival. Most fatigue problems here are itinerary problems rather than willpower problems."]},s("What a checkpoint involves","Police can stop any vehicle and require a breath screening test without suspecting anything. Checkpoints appear on rural roads and at all hours, not only late at night near cities.","The screening test takes seconds. Refusing it is an offence in its own right and is treated more seriously than a positive result, so there is nothing to gain from declining.",["Any vehicle can be stopped","Checkpoints run at all hours","Refusing is worse than failing"])],sources:[{label:"NZTA alcohol and drugs",url:"https://www.nzta.govt.nz/roadcode/general-road-code/about-driver-responsibility/alcohol-and-drugs/"},{label:"NZTA fatigue",url:"https://www.nzta.govt.nz/safety/driving-safely/fatigue/"}]}),
  a({slug:"left-side-driving-new-zealand",title:"Driving on the left in New Zealand for the first time",description:"Turns, roundabouts and quiet-road restarts are the moments when old habits return.",category:"Rules & safety",region:"New Zealand roads",places:["Roundabouts","Rural intersections","One-way streets","Rental depots"],imageAlt:"Left-side driving view on a New Zealand road",intro:"Remembering the left is easiest in flowing traffic and hardest after a stop, on an empty road or while turning. Create simple checks that survive distraction and tiredness.",sections:[s("Set up the cockpit","Adjust mirrors, seat and navigation before moving. Place a small legal reminder where the driver can see it without obstructing the windscreen.","The driver should remain near the centre line and the passenger side near the road edge. Use lane markings rather than copying another vehicle blindly."),s("Slow the decision points","Pause at every turn and look in both directions, then enter the left lane. At roundabouts, give way according to New Zealand rules and signal the intended exit.","Take extra care when restarting from a scenic stop or petrol station, where no traffic may reveal the correct side."),s("Reset without panic","If orientation feels wrong, slow smoothly and stop in a legal safe place. Do not swerve across lanes or reverse into traffic.","Share driving only with people who are licensed, rested and covered by the rental agreement. The first practice session belongs in daylight." ),s("The moments it goes wrong","Experienced drivers do not drift to the wrong side while cruising; they get it wrong at specific moments. Pulling out of a car park or driveway, turning at a quiet intersection, setting off after a rest stop, and the first turn after a distraction are where it happens.","Build a deliberate habit for those moments: say it out loud, look for the centre line on your right, and check the passenger side is nearest the kerb. The driver sits on the right, so if the kerb is on your side, you are on the wrong side of the road.",["Driver sits right, kerb on the left","Errors happen at turns and after stops","Say it out loud at every pull-out"]),s("Set the vehicle up before you move","Adjust the mirrors, seat and navigation before leaving the depot, not while driving. The indicator and wiper stalks are often reversed from what you are used to, and using the wipers instead of the indicator at a junction is the classic first-day mistake.","Practise in the car park first: a few laps, a reverse, and a couple of turns. Ten minutes there is worth an hour of unlearning on a live road."),s("Judging the width and the left side","Sitting on the right means your sense of where the left edge of the vehicle sits is wrong, and drivers new to the left commonly clip kerbs and drift towards the verge. In a campervan that verge is often unsealed with a soft drop.","Use the lane markings rather than instinct, and position with the centre line at a consistent distance from your right shoulder. If you are clipping the left, you are further left than you think.",["You will misjudge the left edge","Position off the centre line","Verges are soft and drop away"]),s("Roundabouts and give way","Roundabouts run clockwise and you give way to your right, which is the opposite of what a right-side driver expects. Approach slowly, look right, and do not commit until you are certain. Multi-lane roundabouts require the correct lane on entry, marked on the road.","At intersections, the current rule is that a turning vehicle gives way to one going straight through. Guidance published before 2012 says the opposite and is still widely circulated, so ignore anything that does not match this."),{heading:"The first day",body:["Do not collect a vehicle and immediately drive a long distance, particularly straight off a long-haul flight. Book somewhere near the pickup point for the first night and keep the first driving day short and on main roads rather than winding rural ones.","Have a passenger act as a second pair of eyes for the first few days, specifically calling out turns and pull-outs. It feels excessive and it prevents exactly the error that causes head-on crashes.","Expect the concentration required to be tiring. Driving on the other side is genuinely more demanding until it becomes automatic, usually after two or three days, so build in more breaks than you normally would."]},s("Overtaking from the left-hand side","Overtaking requires pulling into the oncoming lane on your right, which feels wrong at first and needs a longer clear stretch than you would use at home because your sightline from the right-hand seat is different.","Most New Zealand highways are two-lane with few passing lanes. If overtaking feels marginal, do not; arriving five minutes later is a trade nobody has ever regretted.",["Overtake to the right","Sightlines differ from the right seat","If it feels marginal, do not"])],sources:[nztaVisitors]}),
  a({slug:"one-lane-bridges-gravel-roads-new-zealand",title:"One-lane bridges and gravel roads in New Zealand",description:"Priority signs, dust and loose surfaces need calm decisions from larger vehicles.",category:"Rules & safety",region:"Rural New Zealand",places:["West Coast bridges","Northland gravel roads","East Cape","Backcountry access roads"],imageAlt:"One-lane bridge on a remote New Zealand road",intro:"Rural roads can narrow from a centre line to one bridge deck without much transition. Read the priority sign early, slow on the straight and assume the next vehicle may be larger than it first appears.",sections:[s("Give way correctly","The round red sign indicates that your direction gives way; the blue rectangular sign indicates priority. Priority still requires the bridge to be clear and safe.","Wait well back so an oncoming truck or caravan has room to leave the bridge. Never stop on railway tracks incorporated into a bridge."),s("Adapt to gravel","Reduce speed before the loose surface, increase following distance and avoid abrupt steering or braking. Dust can hide vehicles, cyclists and livestock.","Slow significantly for oncoming traffic to reduce stone damage and maintain control near the edge."),s("Check the contract","Public access does not guarantee that a rental permits the road. Review unsealed-road exclusions and named prohibited routes before leaving the highway.","Turn back at washouts, deep fords or no-exit roads without turning room. A map line is not evidence of current vehicle access." ),s("Reading a one-lane bridge sign","The sign carries two arrows. The large black arrow shows the direction with priority; the small red arrow means you give way. If the red arrow points your way, stop and wait for oncoming traffic to clear before entering.","Slow on approach regardless of who has priority, and look right through the bridge to the far end before committing. Some are long enough that a vehicle can already be on it and not yet visible, and a few include a passing bay mid-span.",["Large black arrow has priority","Look through to the far end first","Slow down even when you have right of way"]),s("Bridges shared with rail","A number of one-lane bridges, particularly on the West Coast, carry a railway line down the middle or alongside the traffic lane. Trains always have priority and the signage and lights must be obeyed absolutely.","Do not stop on these bridges for photographs, and do not enter if lights are flashing. The clearances are tight and there is nowhere to go if you have misjudged it."),s("Driving gravel properly","Reduce speed well below what feels necessary; most gravel crashes happen because the driver was travelling at sealed-road speed. Brake and steer gently and separately, avoid sudden inputs, and expect the vehicle to move around under you, particularly in a corrugated section.","Pull over and slow right down for oncoming vehicles to reduce stone damage to both, and leave a very large gap behind anything throwing dust, because visibility can go to nothing. Windscreen chips are the most common rental damage claim on these roads.",["Slow well below sealed-road speed","Gentle, separate braking and steering","Huge gap behind anything raising dust"]),s("Check your rental agreement first","Most rental agreements prohibit specific unsealed roads by name and some exclude gravel entirely, with damage on them not covered. Skippers Canyon, Ninety Mile Beach and several others are commonly named exclusions, and the vehicle is tracked.","Read the agreement before planning a route that includes gravel, and be aware that a road being open and legal does not mean your insurance follows you onto it. When in doubt, take the sealed alternative."),{heading:"Punctures and windscreen damage",body:["Stone chips are the most common damage on unsealed roads and many excess reduction products exclude glass. Check whether yours does before driving gravel, and consider the separate windscreen cover most operators offer, which is usually inexpensive.","For a puncture, get well off the road before jacking, because a vehicle on a soft or sloping gravel shoulder is genuinely dangerous. Confirm the spare, jack and brace exist and that you know the jacking points before the trip rather than during it.","On a remote gravel road with no reception, staying with the vehicle is the right call. It is shelter, it is visible, and somebody will pass eventually on almost any road that appears on a map."]},s("Dust and following distance","Dust from a vehicle ahead can reduce visibility to nothing within seconds, and it hides oncoming traffic, corners and stock. This is the most underestimated hazard on New Zealand gravel.","Drop well back rather than pushing through, and put headlights on so others can see you. If you cannot see the road, slow to walking pace or stop somewhere visible until it clears.",["Dust hides oncoming traffic","Drop right back, do not push through","Headlights on for gravel"])],sources:[{label:"NZTA visitor driving resources",url:"https://www.nzta.govt.nz/safety/visiting-new-zealand/"}]}),
  a({slug:"wildlife-livestock-road-safety-new-zealand",title:"Wildlife, livestock and rural road safety",description:"Sheep, seals, birds and farm vehicles can enter the road where a visitor expects an empty lane.",category:"Rules & safety",region:"Rural and coastal New Zealand",places:["Kaikōura","Catlins","Otago Peninsula","Rural highways"],imageAlt:"Sheep beside a rural New Zealand road",intro:"New Zealand roads pass working farms and wildlife habitat at close range. Speed and distance are the only reliable tools when an animal behaves unpredictably.",sections:[s("Expect stock","Slow well before sheep, cattle, horses or a farmer controlling movement. Follow gestures and never sound the horn aggressively through a mob.","Manure, mud and wet grass can reduce grip after the animals pass. Accelerate gently and give farm vehicles room."),s("Protect coastal wildlife","At seal and penguin areas, park only in formed spaces and walk the final distance. Keep the legal or advised separation and never stand between an animal and the sea.","Birds may nest beside roads or strike vehicles at dusk. Lower speed around signed habitat and avoid night driving through active areas."),s("After a collision","Stop safely, protect people from traffic and call 111 for an emergency. Report stock or injured protected wildlife to the responsible authority.","Do not handle an injured wild animal without direction. Stress, teeth and traffic can create another casualty." ),s("Stock on the road is normal here","Herds being moved between paddocks on rural roads are routine, and you may come around a corner into a full dairy herd. Slow right down, stop if asked, and follow the directions of the farmer or the person moving them.","Move through slowly and steadily rather than trying to weave; the animals will part around a slow vehicle. Do not sound the horn, which scatters stock and makes it considerably worse for everyone.",["Stop and follow the farmer's directions","Move slowly, do not weave","Never use the horn near stock"]),s("Unfenced roads and wandering animals","Many rural and high country roads are unfenced, and sheep, cattle and deer can be on the carriageway at any time, day or night. This is particularly common in the Mackenzie, Central Otago, Northland and on back roads everywhere.","At night, animals appear at the edge of your headlights with very little warning. Reduce speed on unfenced roads after dark, and be aware that where there is one animal there are usually more."),s("Do not swerve","Braking in a straight line is almost always the correct response to an animal on the road. Swerving is what turns an animal strike into a rollover, a head-on or a departure off the road, and in a high-sided campervan the rollover risk is real.","Possums, hares and rabbits are the most common animals hit and are not worth any evasive action at all. For larger stock, brake hard and straight and accept the impact rather than leaving the road.",["Brake straight, never swerve","Swerving causes rollovers","Possums are not worth evasive action"]),s("Protected wildlife on and near roads","Kea at Arthur's Pass, Homer Tunnel and Fiordland car parks are drawn to vehicles and are regularly killed on roads. Penguins cross roads near the coast in Oamaru, the Catlins and Banks Peninsula, and blue penguins nest under buildings and vehicles.","Never feed kea, which is what brought them to car parks in the first place. Check under and around a parked vehicle before moving it in penguin areas, and drive slowly through signed wildlife zones after dark."),{heading:"Rural driving beyond the animals",body:["Farm vehicles, tractors and stock trucks use rural roads at low speed and turn into unmarked gateways with little warning. Expect mud on the road near farm entrances, which can be as slippery as ice on a sealed surface.","Logging trucks on West Coast and central North Island roads are wide, fast and cannot move over much. Give them the full lane, slow down when one approaches on a narrow section, and do not attempt to overtake one on a winding road.","Many rural intersections have limited visibility because of hedges and shelter belts. Treat every uncontrolled rural intersection as one where something may emerge, and remember that local drivers know the road and you do not."]},s("Reporting an animal strike","Hitting stock is a matter for the farmer and you should stop and report it, both because the animal may need attention and because the owner needs to know. Hitting protected wildlife should be reported to DOC.","Do not attempt to move an injured large animal yourself. Note the location, call it in, and be aware that a live animal on the road is a hazard to the next vehicle as well.",["Stop and report stock strikes","Report protected wildlife to DOC","Do not handle injured animals"])]}),
  a({slug:"camping-rules-local-councils-new-zealand",title:"Why camping rules change between New Zealand councils",description:"District bylaws can define prohibited areas, time limits and sites for vehicles without certification.",category:"Rules & safety",region:"New Zealand districts",places:["Queenstown Lakes","Auckland","Tasman","Rotorua Lakes","Southland"],imageAlt:"Council freedom camping information sign",intro:"New Zealand has a national freedom-camping framework but no single nationwide map of every permitted bay. Councils translate local pressure, reserves and infrastructure into bylaws and site notices.",sections:[s("Read the current bylaw","Search the official council page for the district, then compare the map, written bylaw and sign at the location. Boundaries can follow reserve parcels rather than obvious roads.","A general app listing should lead to the authority, not replace it. Download the official map before travelling beyond reception."),s("Understand site-specific differences","One council may allow only certified self-contained vehicles, while another names toilets where other campers can stay. Maximum nights, arrival hours and seasonal closures also vary.","Parking rules and freedom-camping rules can both apply. Paying for daytime parking does not automatically buy an overnight right."),s("When information conflicts","Follow the current physical sign and contact the council when online documents disagree. Do not rely on a review written before a bylaw change.","Move to a campground if doubt remains. A legal backup prevents a late search from becoming parking in a prohibited area." ),s("Why the rules differ at every boundary","The Freedom Camping Act 2011 lets each territorial authority make its own bylaw for its own district. That is the entire explanation: there are dozens of councils, each responding to different pressure from residents, different site conditions and different enforcement budgets.","The practical consequence is that a rule you confirmed in one district tells you nothing about the next one, and the boundary is frequently invisible from the road. Assuming continuity is the single most common cause of an infringement.",["Every council writes its own bylaw","District boundaries are invisible","Never carry a rule across a boundary"]),s("The strictest districts","Queenstown Lakes, Auckland, Tasman, Thames-Coromandel and Kaikōura all run tight regimes with defined sites, certification requirements, time windows and active patrols. These are also the districts with the highest demand, which is precisely why the rules tightened.","More permissive districts still have prohibited areas and stay limits. Permissive does not mean unregulated, and the sign at the specific location remains the authority regardless of the district's general reputation."),s("How to check quickly","Work out which district you are in, then find that council's freedom camping page or bylaw map. Most publish a map of permitted sites, which is faster to use than reading the bylaw text and is what enforcement officers are working from.","Do this while you still have reception, ideally the evening before rather than at dusk when you are tired and looking for somewhere to stop. Screenshot the map for the district you will be in tomorrow.",["Find the council, then the bylaw map","Check the night before, not at dusk","Screenshot the map for tomorrow"]),s("When the sign and the map disagree","Follow the sign. Councils install temporary restrictions after flooding, slips, events and antisocial behaviour, and those appear physically on the ground long before they reach any published map or third-party dataset.","If a site is full, do not create an overflow line along the access road. That behaviour is what closes sites permanently, and it is the reason a district that was relaxed five years ago is now heavily restricted."),{heading:"What enforcement actually looks like",body:["Officers typically patrol at dusk and again around dawn in high-demand districts, and they check the registration against the self-containment register rather than looking at the sticker. The infringement attaches to the vehicle, so a rental company passes it to you with an administration fee added.","Some councils issue a warning first and others do not, and there is no consistency to rely on. Assume the first contact will be an infringement, because in the busiest districts it usually is.","Disputing one afterwards is difficult without evidence. Photographing the sign when you arrive costs nothing and is the only thing that reliably helps if a dispute arises later."]},s("Why the rules keep tightening","Restrictions have expanded over the last decade largely in response to waste, overcrowding and antisocial behaviour at a small number of sites. Councils respond to resident complaints, and closures are usually the end point of a documented problem.","Behaving well is therefore not just courtesy but the mechanism that keeps sites open. The districts with the strictest rules today are the ones where visitor behaviour was worst five years ago.",["Rules tighten after complaints","Closures follow documented problems","Behaviour keeps sites open"])],sources:[{label:"MBIE freedom camping information",url:"https://www.mbie.govt.nz/immigration-and-tourism/tourism/tourism-projects/freedom-camping"}]}),
];
